import React, { useState } from 'react';
import { LoginForm } from '@/components/LoginForm';
import { RegistrationForm } from '@/components/RegistrationForm';
import { PasswordResetForm } from '@/components/PasswordResetForm';
import { BrandSidebar } from '@/components/BrandSidebar';
import { Dashboard } from '@/components/dashboard/Dashboard';
import { ContactForm } from '@/components/ContactForm';
import { NotFound } from '@/components/NotFound';
import { LandingPage } from '@/components/LandingPage';
import { Modal } from '@/components/ui/Modal';
import { CheckCircle2 } from 'lucide-react';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  // Default view is now 'landing'
  const [currentView, setCurrentView] = useState<'landing' | 'login' | 'register' | 'forgot-password' | 'not-found'>('landing');
  const [isSupportModalOpen, setIsSupportModalOpen] = useState(false);

  const handleLoginSuccess = () => {
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentView('landing'); // Return to landing page on logout
  };

  if (isAuthenticated) {
    return <Dashboard onLogout={handleLogout} />;
  }

  // Render Landing Page (Full Width)
  if (currentView === 'landing') {
    return (
      <LandingPage 
        onLogin={() => setCurrentView('login')} 
        onRegister={() => setCurrentView('register')} 
      />
    );
  }

  // Render 404 Page (Full Screen)
  if (currentView === 'not-found') {
    return (
      <>
        <NotFound 
          onGoHome={() => setCurrentView('landing')} 
          onContactSupport={() => setIsSupportModalOpen(true)}
        />
        <Modal
          isOpen={isSupportModalOpen}
          onClose={() => setIsSupportModalOpen(false)}
          title="Contact Support"
          className="max-w-lg"
        >
          <div className="mb-6">
             <p className="text-sm text-gray-500">Can't find what you need? Send us a message.</p>
          </div>
          <ContactForm />
        </Modal>
      </>
    );
  }

  // Auth Layout (Split Screen)
  return (
    <div className="min-h-screen w-full flex overflow-hidden bg-white selection:bg-brand-100 selection:text-brand-900">
      {/* Left Side - Brand & Visuals (Hidden on mobile, visible on large screens) */}
      <aside className="hidden lg:flex lg:w-1/2 xl:w-5/12 relative overflow-hidden bg-brand-900 text-white">
        <BrandSidebar />
      </aside>

      {/* Right Side - Form Container */}
      <main className="w-full lg:w-1/2 xl:w-7/12 flex flex-col items-center p-6 sm:p-12 lg:p-24 relative z-10 min-h-screen">

        {/* Centered Content */}
        <div className="w-full max-w-md animate-fade-in-up my-auto" key={currentView}>
          {/* Mobile Logo / Brand Header */}
          <header className="lg:hidden mb-10 text-center">
            <div className="h-12 w-12 bg-brand-600 rounded-xl mx-auto mb-4 shadow-lg shadow-brand-600/30 flex items-center justify-center text-white">
              <CheckCircle2 className="w-8 h-8" />
            </div>
            <h1 className="text-2xl font-bold text-gray-900 font-sans">Kriyadocs RVS</h1>
          </header>

          {currentView === 'login' ? (
            <LoginForm 
              onRegisterClick={() => setCurrentView('register')} 
              onForgotPasswordClick={() => setCurrentView('forgot-password')}
              onLoginSuccess={handleLoginSuccess}
            />
          ) : currentView === 'register' ? (
            <RegistrationForm onLoginClick={() => setCurrentView('login')} />
          ) : (
            <PasswordResetForm onBackToLogin={() => setCurrentView('login')} />
          )}

          <div className="mt-12 text-center border-t border-gray-100 pt-6">
            <div className="flex flex-col gap-2">
              <p className="text-sm text-gray-400">
                Need help? <a href="#" onClick={(e) => { e.preventDefault(); setIsSupportModalOpen(true); }} className="font-medium text-brand-600 hover:text-brand-500 transition-colors">Contact Support</a>
              </p>
              <button 
                onClick={() => setCurrentView('landing')}
                className="text-xs text-gray-400 hover:text-gray-600 transition-colors"
              >
                ← Back to Home
              </button>
            </div>
          </div>
        </div>

        {/* Footer decoration - Pushed to bottom via flex */}
        <footer className="mt-auto pt-6 text-center w-full text-xs text-gray-300 lg:text-gray-400">
          &copy; {new Date().getFullYear()} Kriyadocs RVS. All rights reserved.
          <span className="mx-2 opacity-50">|</span>
          <button 
            onClick={() => setCurrentView('not-found')} 
            className="hover:text-brand-600 transition-colors"
            title="Preview 404 Page"
          >
            Preview 404
          </button>
        </footer>
      </main>

      {/* Support Modal */}
      <Modal
        isOpen={isSupportModalOpen}
        onClose={() => setIsSupportModalOpen(false)}
        title="Contact Support"
        className="max-w-lg"
      >
        <div className="mb-6">
           <p className="text-sm text-gray-500">Can't find what you need? Send us a message.</p>
        </div>
        <ContactForm />
      </Modal>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  UploadCloud, 
  FileText, 
  CheckCircle, 
  XCircle, 
  Download, 
  AlertCircle, 
  Loader2, 
  RefreshCw,
  Search,
  ChevronRight,
  ShieldAlert,
  Database,
  ExternalLink
} from 'lucide-react';
import { Button } from '@/components/ui/Button';

type ValidationStatus = 'idle' | 'uploading' | 'processing' | 'complete';

// Reusable grainy blob from landing page for consistency
const GrainyBlob: React.FC<{ colorClass: string; className?: string }> = ({ colorClass, className = "relative" }) => (
  <div className={`${className} pointer-events-none`}>
    <div className={`absolute inset-0 rounded-full ${colorClass} opacity-20`} style={{ filter: 'url(#grainy-noise)' }}></div>
    <div className={`absolute inset-0 rounded-full ${colorClass} mix-blend-multiply opacity-10`}></div>
  </div>
);

export const ReferenceValidator: React.FC = () => {
  const [status, setStatus] = useState<ValidationStatus>('idle');
  const [file, setFile] = useState<File | null>(null);
  const [progress, setProgress] = useState(0);
  const [logMessages, setLogMessages] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  // Mock Issues for the results preview
  const mockIssues = [
    { id: 1, ref: "Smith, J. et al (2022). 'Quantum Mechanics in Biology'. Nature.", error: "Year mismatch (Crossref: 2021)", type: "Warning" },
    { id: 2, ref: "Doe, A. (2019). 'The Future of AI'. Journal of Science.", error: "Retracted Paper Detected", type: "Critical" },
    { id: 3, ref: "Brown, L. (2023). 'Ethics in Research'. Bioethics Monthly.", error: "DOI not found in PubMed", type: "Missing" },
  ];

  const processingSteps = [
    "Initializing JATS XML parser...",
    "Extracting bibliography metadata...",
    "Mapping 142 citation strings...",
    "Connecting to Crossref API...",
    "Cross-checking DOIs against central registry...",
    "Querying PubMed for PMIDs...",
    "Verifying author ORCID credentials...",
    "Detecting retracted papers (Shield Integrity)...",
    "Finalizing validation report..."
  ];

  useEffect(() => {
    if (status === 'processing') {
      let step = 0;
      const interval = setInterval(() => {
        if (step < processingSteps.length) {
          setLogMessages(prev => [...prev, processingSteps[step]]);
          step++;
        } else {
          clearInterval(interval);
          setTimeout(() => setStatus('complete'), 800);
        }
      }, 600);
      return () => clearInterval(interval);
    }
  }, [status]);

  useEffect(() => {
    logEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logMessages]);

  const handleFileDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const droppedFile = e.dataTransfer.files[0];
    if (droppedFile) setFile(droppedFile);
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleRemoveFile = (e: React.MouseEvent) => {
    e.stopPropagation();
