    { id: 1, ref: "Smith, J. et al (2022). 'Quantum Mechanics in Biology'. Nature.", error: "Year mismatch (Crossref: 2021)", type: "Warning" },
    { id: 2, ref: "Doe, A. (2019). 'The Future of AI'. Journal of Science.", error: "Retracted Paper Detected", type: "Critical" },
