    if (status === 'processing') {
      let step = 0;
      const interval = setInterval(() => {
        if (step < processingSteps.length) {
          setLogMessages(prev => [...prev, processingSteps[step]]);
          step++;
        } else {
          clearInterval(interval);
          setTimeout(() => setStatus('complete'), 800);
